arguments.command:
cd /tmp && python3 - <<'EOF'
import urllib.request, urllib.parse, json, time

def s2(query, n=12):
    url = "https://api.semanticscholar.org/graph/v1/paper/search?" + urllib.parse.urlencode({
        "query": query, "fields": "title,year,venue,externalIds,citationCount,abstract", "limit": n})
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    for attempt in range(3):
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return json.load(r).get("data", [])
        except Exception as e:
            print("  retry", query, e)
            time.sleep(10)
    return []

queries = ["animal behavior recognition video",
           "dog action recognition",
           "cat behavior recognition",
           "pet action recognition",
           "livestock cattle behavior recognition deep learning",
           "animal welfare video monitoring"]
allp = {}
for q in queries:
    print("==", q)
    for p in s2(q):
        eid = p.get("externalIds") or {}
        aid = eid.get("ArXiv") or ""
        key = aid or eid.get("DOI") or p.get("title","")[:50]
        if key in allp: continue
        allp[key] = {"title": p.get("title"), "year": p.get("year"), "venue": p.get("venue") or "",
                     "arxiv": aid, "doi": eid.get("DOI",""), "cites": p.get("citationCount")}
    time.sleep(2)
json.dump(allp, open("s2_results.json","w"), ensure_ascii=False, indent=1)
print(len(allp), "papers saved")
EOF

